const MAX_REWARD_ITEMS = 20;
function formatDisplayAmount(amount) {
  const numeric = Number.parseFloat(amount.toExact());
  if (!Number.isFinite(numeric) || numeric === 0) {
    return "0";
  }
  const abs = Math.abs(numeric);
  if (abs >= 1e3) {
    return (numeric / 1e3).toLocaleString(void 0, { maximumFractionDigits: 2 }) + "K";
  }
  if (abs >= 1) {
    return numeric.toFixed(2);
  }
  if (abs >= 1e-3) {
    return numeric.toFixed(4);
  }
  const exponent = Math.floor(Math.log10(abs));
  const scaled = numeric / Math.pow(10, exponent);
  return `${scaled.toFixed(2)}e${exponent}`;
}
